mapper.select:
select t.crp_id,t.crp_id crpId,t.cpa_id cpaId,p.service_price,p.service_price
servicePrice,t.create_time,t.create_time
createTime,p.price,t.start_time,t.start_time startTime,t.remark,t.status_cd,t.status_cd
statusCd,t.end_time,t.end_time endTime,t.rule_id,t.rule_id ruleId,t.community_id,t.community_id
communityId,p.type cpaType,td.`name` cpaTypeName
from charge_rule_price t
LEFT JOIN charge_peak_alley_price p on t.cpa_id = p.cpa_id
LEFT JOIN t_dict td on td.status_cd = p.type and td.table_name = 'charge_peak_alley_price' and td.table_columns
= 'type'
where 1 =1

    and t.crp_id= #{crpId}


    and t.service_price= #{servicePrice}


    and t.create_time= #{createTime}


    and t.price= #{price}


    and t.start_time= #{startTime}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.end_time= #{endTime}


    and t.rule_id= #{ruleId}


    and t.community_id= #{communityId}

order by t.start_time

    limit #{page}, #{row}

mapper.update:
